--
-- Table structure for table `barangay_referral_updates`
--

DROP TABLE IF EXISTS `barangay_referral_updates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `barangay_referral_updates` (
  `update_id` int NOT NULL AUTO_INCREMENT,
  `referral_id` int NOT NULL,
  `update_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'acknowledged, dispatched, picked_up, held, impounded, claimed, adopted, not_found, other',
  `source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'barangay_reported' COMMENT 'barangay_reported or straysafe_user',
  `update_date` date NOT NULL,
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `evidence_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_after` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responder_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assistance_provided` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `progress_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `follow_up_instructions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `additional_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `supporting_documents` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `recorded_by` int DEFAULT NULL,
  `recorded_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`update_id`),
  KEY `ix_barangay_referral_updates_update_id` (`update_id`),
  KEY `ix_barangay_referral_updates_referral_id` (`referral_id`),
  KEY `fk_barangay_referral_updates_recorded_by` (`recorded_by`),
  CONSTRAINT `fk_barangay_referral_updates_recorded_by` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_barangay_referral_updates_referral_id` FOREIGN KEY (`referral_id`) REFERENCES `barangay_referrals` (`referral_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

