INSERT INTO `case_contact_logs` VALUES (1,1,1,'message','Xenomorph Allen (possible owner)','Hello! The Subdivision Administration received a report involving an animal that may match your registered pet. We would like to verify whether this animal belongs to you. Please review the details and select Confirm Ownership or Decline Ownership.\n\nSubdivision Office Contact (Phone Call): 09770328167 · Representative: Leilah Montoya\n\nReview the reported animal\'s photos and details, then Confirm or Decline Ownership here: /resident-app/ownership/1','other','2026-11-20 17:12:34',1,'2026-11-20 17:12:34'),(2,7,1,'message','Kai (reporter)','ghvghvgv\n\nView report details: /resident-app/reports/SS-2026-0007','other','2026-11-21 04:09:31',1,'2026-11-21 04:09:31'),(3,15,1,'message','Siegfrid U. Jacinto (owner)','Good things come to those who wait\n\nView report details: /resident-app/reports/SS-2026-0015','other','2026-11-22 19:41:44',1,'2026-11-22 19:41:44'),(4,19,1,'message','Kai (possible owner)','Hello! The Subdivision Administration received a report involving an animal that may match your registered pet. We would like to verify whether this animal belongs to you. Please review the details and select Confirm Ownership or Decline Ownership.\n\nReview the reported animal\'s photos and details, then Confirm or Decline Ownership here: /resident-app/ownership/2','other','2026-11-23 05:31:30',1,'2026-11-23 05:31:30'),(5,19,1,'message','Emmanuel Vito Cruz (possible owner)','Hello! The Subdivision Administration received a report involving an animal that may match your registered pet. We would like to verify whether this animal belongs to you. Please review the details and select Confirm Ownership or Decline Ownership.\n\nReview the reported animal\'s photos and details, then Confirm or Decline Ownership here: /resident-app/ownership/3','other','2026-11-23 05:42:09',1,'2026-11-23 05:42:09'),(6,19,1,'phone','Emmanuel Vito Cruz (owner)','Ikukulong niya na daw yung aso','cooperative','2026-11-23 06:01:00',1,'2026-11-23 06:01:41');
