INSERT INTO `case_messages` VALUES (1,1,NULL,'system','Ownership verification for Report SS-2026-0001. The reported animal: Cat · Puspin (Pusang Pinoy) · White. Reported on 20 Nov 2026 in Selera Homes. The Subdivision Administration asks whether it is your registered pet Yumiii. Answer below with “Yes, this is my pet” or “No, this is not my pet”, or write here. Nothing about ownership changes until the Subdivision Administration verifies it. The reporter’s details are not shared.',NULL,'2026-11-20 17:12:34'),(2,1,1,'message','Hello! The Subdivision Administration received a report involving an animal that may match your registered pet. We would like to verify whether this animal belongs to you. Please review the details and select Confirm Ownership or Decline Ownership.\n\nSubdivision Office Contact (Phone Call): 09770328167 · Representative: Leilah Montoya\n\nReview the reported animal\'s photos and details, then Confirm or Decline Ownership here: /resident-app/ownership/1','msg-mworflih-s8euxsrln2','2026-11-20 17:12:34'),(3,1,5,'message','Yes, this is my pet Yumiii.',NULL,'2026-11-20 17:16:08'),(4,2,NULL,'system','The owner confirmed the pet is safely home.',NULL,'2026-11-20 18:04:15'),(5,1,NULL,'system','The Subdivision Administration verified that the reported animal is your registered pet Yumiii.',NULL,'2026-11-20 18:43:45'),(6,1,NULL,'system','The report is closed (No further sightings; monitoring ended).',NULL,'2026-11-20 18:48:04'),(7,3,1,'message','ghvghvgv\n\nView report details: /resident-app/reports/SS-2026-0007','cm-mwpexdlt-n669gjy3wj','2026-11-21 04:09:31'),(8,3,3,'message','njnjknjknjk','case-mwpey34t-8ohde6ultur','2026-11-21 04:10:04'),(9,4,57,'message','matagal pa ba?','case-mwrrkflu-0ue2kf36b39','2026-11-22 19:39:25'),(10,4,57,'message','natatae na ako kakahintay','case-mwrrknja-5oaoelpk5k','2026-11-22 19:39:36'),(11,4,1,'message','Good things come to those who wait\n\nView report details: /resident-app/reports/SS-2026-0015','inbox-mwrro0bj-nc1ohfylj2','2026-11-22 19:41:43'),(12,4,NULL,'system','The owner confirmed the pet is safely home.',NULL,'2026-11-22 19:47:45'),(13,5,NULL,'system','Ownership verification for Report SS-2026-0019. The reported animal: Dog · Aspin (Asong Pinoy) · tan. Reported on 23 Nov 2026 in Selera Homes. The Subdivision Administration asks whether it is your registered pet Ruru. Answer below with “Yes, this is my pet” or “No, this is not my pet”, or write here. Nothing about ownership changes until the Subdivision Administration verifies it. The reporter’s details are not shared.',NULL,'2026-11-23 05:31:30'),(14,5,1,'message','Hello! The Subdivision Administration received a report involving an animal that may match your registered pet. We would like to verify whether this animal belongs to you. Please review the details and select Confirm Ownership or Decline Ownership.\n\nReview the reported animal\'s photos and details, then Confirm or Decline Ownership here: /resident-app/ownership/2','msg-mwscqga3-sjmx2sihir','2026-11-23 05:31:30'),(15,5,3,'message','No, this is not my pet Ruru.',NULL,'2026-11-23 05:32:47'),(16,6,NULL,'system','Ownership verification for Report SS-2026-0019. The reported animal: Dog · Aspin (Asong Pinoy) · tan. Reported on 23 Nov 2026 in Selera Homes. The Subdivision Administration asks whether it is your registered pet Mochi. Answer below with “Yes, this is my pet” or “No, this is not my pet”, or write here. Nothing about ownership changes until the Subdivision Administration verifies it. The reporter’s details are not shared.',NULL,'2026-11-23 05:42:09'),(17,6,1,'message','Hello! The Subdivision Administration received a report involving an animal that may match your registered pet. We would like to verify whether this animal belongs to you. Please review the details and select Confirm Ownership or Decline Ownership.\n\nReview the reported animal\'s photos and details, then Confirm or Decline Ownership here: /resident-app/ownership/3','msg-mwsd3wsw-ljsl8av4nt','2026-11-23 05:42:09'),(18,6,2,'message','Yes, this is my pet Mochi.',NULL,'2026-11-23 05:43:01'),(19,6,NULL,'system','The Subdivision Administration verified that the reported animal is your registered pet Mochi.',NULL,'2026-11-23 06:12:07'),(20,7,1,'message','Your requested QR collar for Kobe (Dog · Shih Tzu · Black, White · Ref SS-0078) is ready for pickup. Please coordinate with the Subdivision Administration regarding its collection.\n\nRequest Reference: QCR-0001 · Pet: Kobe (Dog · Shih Tzu · Black, White · Ref SS-0078)',NULL,'2026-11-23 09:55:47');
