DROP TABLE IF EXISTS `pets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pets` (
  `pet_id` int NOT NULL AUTO_INCREMENT,
  `owner_id` int DEFAULT NULL,
  `pet_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pet_type` enum('Dog','Cat') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `breed` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_markings` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `colors` json DEFAULT NULL,
  `primary_color` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secondary_color` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tertiary_color` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `distinctive_markings` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `gender` enum('Male','Female','Unknown') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Unknown',
  `birth_date` date DEFAULT NULL,
  `estimated_age` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weight` decimal(5,2) DEFAULT NULL,
  `size_category` enum('Small','Medium','Large') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Medium',
  `photo_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_front_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_left_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_right_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vaccine_card_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `health_condition` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `is_vaccinated` tinyint(1) DEFAULT '0',
  `vaccination_date` date DEFAULT NULL,
  `vaccine_expiry` date DEFAULT NULL,
  `is_neutered` tinyint(1) DEFAULT '0',
  `temperament` enum('Friendly','Aggressive','Anxious','Scared','Protective') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Friendly',
  `has_bite_history` tinyint(1) DEFAULT '0',
  `bite_incident_count` int DEFAULT '0',
  `chase_behavior` tinyint(1) DEFAULT '0',
  `chase_incident_count` int DEFAULT '0',
  `declared_bite_history` tinyint(1) NOT NULL DEFAULT '0',
  `declared_chase_behavior` tinyint(1) NOT NULL DEFAULT '0',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` enum('Active','Lost','Found','Rescued','Deceased','Archived','Inactive') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Active',
  `is_verified` tinyint(1) DEFAULT '0',
  `last_seen_lat` decimal(10,8) DEFAULT NULL,
  `last_seen_lng` decimal(11,8) DEFAULT NULL,
  `last_seen_at` timestamp NULL DEFAULT NULL,
  `emergency_contact_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergency_contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `registered_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `registered_latitude` decimal(10,8) DEFAULT NULL,
  `registered_longitude` decimal(11,8) DEFAULT NULL,
  `registered_by_user_id` int DEFAULT NULL,
  `registered_by_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_check_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `merged_into_pet_id` int DEFAULT NULL,
  `ai_detection_confidence` decimal(4,3) DEFAULT NULL,
  `photo_check_details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`pet_id`),
  UNIQUE KEY `uq_pets_reference_code` (`reference_code`),
  KEY `idx_pets_owner` (`owner_id`),
  KEY `idx_pets_status` (`status`),
  KEY `fk_pets_registered_by` (`registered_by_user_id`),
  KEY `idx_pets_status_type` (`status`,`pet_type`),
  KEY `idx_pets_owner_status` (`owner_id`,`status`),
  CONSTRAINT `fk_pets_owner` FOREIGN KEY (`owner_id`) REFERENCES `users` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pets_registered_by` FOREIGN KEY (`registered_by_user_id`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

