INSERT INTO `system_settings` VALUES (1,'pet_reference_seq','78',1,'Last issued Animal Reference Code number (SS-0001, SS-0002, ...)','2026-11-23 09:53:06',NULL),(2,'gemini_vision_matching','vision',1,'Toggle between Google Gemini Vision AI Biometrics and Free-Tier Attribute Rule-Based Matching','2026-11-20 16:16:42',NULL),(3,'case_settings:1','{\"categories\": {\"lost_pet\": true, \"found_animal\": true, \"nuisance\": true, \"safety\": true, \"injured\": true, \"other\": true}, \"policies\": [{\"id\": \"pol-leash-confinement\", \"title\": \"Leash and Confinement Requirement for Domestic Pets\", \"reference\": \"House Rules & By-Laws Art. IV \\u00a74.1\", \"summary\": \"All dogs and domestic pets must be kept securely confined within the resident\'s premises. When in common subdivision areas (streets, parks, sidewalks), pets must be on a secure leash not exceeding 1.5 meters held by a responsible person capable of controlling the animal. Unattended roaming animals are strictly prohibited.\", \"applies_to\": [\"nuisance\", \"safety\", \"lost_pet\", \"found_animal\"], \"observation_days\": 7, \"status\": \"confirmed\", \"fine_amount\": 1000.0, \"count_window_days\": 180}, {\"id\": \"pol-noise-nuisance\", \"title\": \"Control of Excessive Animal Noise and Habitual Barking\", \"reference\": \"House Rules & By-Laws Art. IV \\u00a74.2\", \"summary\": \"Pet owners must prevent continuous or habitual barking, howling, whining, or noise that causes disturbance to neighbors, especially during designated quiet hours (10:00 PM to 6:00 AM). Continuous barking exceeding 15 consecutive minutes is deemed a community nuisance.\", \"applies_to\": [\"nuisance\"], \"observation_days\": 7, \"status\": \"confirmed\", \"fine_amount\": 1000.0, \"count_window_days\": 180}, {\"id\": \"pol-waste-sanitation\", \"title\": \"Mandatory Pet Waste Clean-Up and Environmental Sanitation\", \"reference\": \"House Rules & By-Laws Art. IV \\u00a74.3\", \"summary\": \"Pet owners are strictly required to clean up, bag, and properly dispose of their pet\'s fecal waste immediately when walking their animals within subdivision roads, sidewalks, open spaces, and common areas. Accumulation of pet waste generating unsanitary odor on private lots is also prohibited.\", \"applies_to\": [\"nuisance\", \"other\"], \"observation_days\": 5, \"status\": \"confirmed\", \"fine_amount\": 500.0, \"count_window_days\": 90}, {\"id\": \"pol-aggressive-bite-control\", \"title\": \"Aggressive Animal Control and Mandatory Bite Incident Protocol\", \"reference\": \"House Rules & By-Laws Art. IV \\u00a74.4\", \"summary\": \"Animals demonstrating aggressive tendencies, charging at pedestrians, or chasing moving vehicles must be muzzled and double-leashed in public spaces. In any bite or scratch incident, the owner is strictly liable for all victim medical expenses (including post-exposure prophylaxis) and must quarantine the animal for a mandatory 14-day rabies observation period.\", \"applies_to\": [\"safety\", \"injured\"], \"observation_days\": 14, \"status\": \"confirmed\", \"fine_amount\": 2500.0, \"count_window_days\": 365}, {\"id\": \"pol-pet-registration-vaccination\", \"title\": \"Subdivision Pet Registration, QR Tagging, and Annual Rabies Immunization\", \"reference\": \"House Rules & By-Laws Art. IV \\u00a74.5\", \"summary\": \"All resident pet owners must register their dogs and cats in the official Subdivision Pet Registry, equip their pets with the StraySafe QR collar tag, and maintain up-to-date annual anti-rabies vaccination records with the HOA administration.\", \"applies_to\": [\"lost_pet\", \"found_animal\", \"nuisance\", \"safety\", \"other\"], \"observation_days\": 14, \"status\": \"confirmed\", \"fine_amount\": 1500.0, \"count_window_days\": 180}], \"followups\": {\"default_days\": 7, \"min_days\": 0, \"max_days\": 90}, \"publication\": {\"lost_pet\": \"review\", \"found_animal\": \"review\"}, \"office\": {\"administration_name\": \"Selera Homes Subdivision Administration\", \"contact_person\": \"\", \"address\": \"\", \"phone\": \"\", \"email\": \"\", \"hours\": \"\"}, \"external_coordination\": {\"barangay_name\": \"Barangay San Vicente\", \"contact_person\": \"Leon Guerrero\", \"phone\": \"09824209283\", \"email\": \"leonguerrero@gmail.com\", \"address\": \"San Vicente, San Jose Del Monte\", \"agencies\": [{\"id\": \"agency-mwos1v6n-4xg1e\", \"name\": \"Barangay San Vicente\", \"agency_type\": \"barangay\", \"contact_person\": \"Leon Guerrero\", \"phone\": \"09824209283\", \"email\": \"leonguerrero@gmail.com\", \"address\": \"San Vicente, San Jose Del Monte\"}]}}',1,'Case workflow settings for subdivision 1','2026-11-21 10:02:40',NULL);
